// === Tab: ribbon ===
	const STEP =2;

	const DIRS = [new p5.Vector(0,-1),  //TOP
							new p5.Vector(1,0),  //RIGHT
							new p5.Vector(0,1),  //DOWN
							new p5.Vector(-1,0)]; //LEFT

	const SHADOW = [new p5.Vector(1,0),  //TOP
							new p5.Vector(0,1),  //RIGHT
							new p5.Vector(1,0),  //DOWN
							new p5.Vector(0,1)]; //LEFT

	const SIZE = 40; //Pair!!
	const HALF_SIZE = SIZE / 2;
	const VERTEX = [[-HALF_SIZE,-STEP,HALF_SIZE,0],  //TOP
							[0,-HALF_SIZE,STEP,HALF_SIZE],  //RIGHT
							[-HALF_SIZE,0,HALF_SIZE,STEP],  //DOWN
							[-STEP,-HALF_SIZE,0,HALF_SIZE]]; //LEFT

	const FOLD_COLOR = ["#000000", "#FFFFAA", "#FFFFAA", "#000000"];

	const SHADOW_OFFSET = 3;

class Ribbon{
	constructor(pos, dirIndex, nextLength, baseColor){
		this.dirIndex = dirIndex;
		this.currDir= DIRS[dirIndex];
		this.currVertex = VERTEX[dirIndex];
		this.prevIndex = 0;

		this.pos = pos;
		this.foldPos = null;
		this.length = 0;
		this.nextLength = nextLength;
		this.changeDirCount = 0;
		this.isChangingDir = false;
		this.baseColor = baseColor;
		this.currColor = baseColor;
	}

	show () {
		drawingContext.shadowBlur = 1;
		drawingContext.shadowColor = "#00000055";
		noStroke();

		if(this.checkNewDirection())
		{
			this.currDir = DIRS[this.dirIndex];
			this.currVertex = VERTEX[this.dirIndex];

			this.nextLength = Math.round(100+random()*200);
			this.length = 0;

			this.isChangingDir = true;
			this.changeDirCount = 0;

			//fix pos
			this.foldPos = this.pos.copy();
			let fixPos = DIRS[this.prevIndex].copy();
			this.pos.add(fixPos.mult(HALF_SIZE ));
			fixPos = this.currDir.copy();
			this.pos.add(fixPos.mult(-HALF_SIZE ));
		}

		if(this.isChangingDir){
			let prevDir = DIRS[this.prevIndex].copy();
			let prevVertex = VERTEX[this.prevIndex];

			drawingContext.shadowOffsetX = SHADOW[this.prevIndex].x*SHADOW_OFFSET;
			drawingContext.shadowOffsetY = SHADOW[this.prevIndex].y*SHADOW_OFFSET;
			fill(this.baseColor);	
			beginShape();
				vertex(this.foldPos.x + prevVertex[0] + ((this.currDir.x*prevVertex[0]<0)?(this.currDir.x*this.changeDirCount):0),
							 this.foldPos.y + prevVertex[1] + ((this.currDir.y*prevVertex[1]<0)?(this.currDir.y*this.changeDirCount):0));
				vertex(this.foldPos.x + prevVertex[2] + ((this.currDir.x*prevVertex[2]<0)?(this.currDir.x*this.changeDirCount):0), 
							 this.foldPos.y + prevVertex[1] + ((this.currDir.y*prevVertex[1]<0)?(this.currDir.y*this.changeDirCount):0));
				vertex(this.foldPos.x + prevVertex[2] + ((this.currDir.x*prevVertex[2]<0)?(this.currDir.x*this.changeDirCount):0),
							 this.foldPos.y + prevVertex[3] + ((this.currDir.y*prevVertex[3]<0)?(this.currDir.y*this.changeDirCount):0));
				vertex(this.foldPos.x + prevVertex[0] + ((this.currDir.x*prevVertex[0]<0)?(this.currDir.x*this.changeDirCount):0),
							 this.foldPos.y + prevVertex[3] + ((this.currDir.y*prevVertex[3]<0)?(this.currDir.y*this.changeDirCount):0));
			endShape(CLOSE);

			let foldStep = prevDir.copy();
			foldStep.mult(STEP);
			this.foldPos.add(foldStep);

			drawingContext.shadowOffsetX = SHADOW[this.dirIndex].x*SHADOW_OFFSET;
			drawingContext.shadowOffsetY = SHADOW[this.dirIndex].y*SHADOW_OFFSET;
			this.currColor = lerpColor(color(FOLD_COLOR[this.dirIndex]), color(this.baseColor), this.changeDirCount/SIZE/4+0.75);
			fill(this.currColor);
			beginShape();
				vertex(this.pos.x + this.currVertex[0] + ((prevDir.x*this.currVertex[0]>0)?(prevDir.x*(this.changeDirCount-SIZE)):0),
							 this.pos.y + this.currVertex[1] + ((prevDir.y*this.currVertex[1]>0)?(prevDir.y*(this.changeDirCount-SIZE)):0));
				vertex(this.pos.x + this.currVertex[2] + ((prevDir.x*this.currVertex[2]>0)?(prevDir.x*(this.changeDirCount-SIZE)):0), 
							 this.pos.y + this.currVertex[1] + ((prevDir.y*this.currVertex[1]>0)?(prevDir.y*(this.changeDirCount-SIZE)):0));
				vertex(this.pos.x + this.currVertex[2] + ((prevDir.x*this.currVertex[2]>0)?(prevDir.x*(this.changeDirCount-SIZE)):0),
							 this.pos.y + this.currVertex[3] + ((prevDir.y*this.currVertex[3]>0)?(prevDir.y*(this.changeDirCount-SIZE)):0));
				vertex(this.pos.x + this.currVertex[0] + ((prevDir.x*this.currVertex[0]>0)?(prevDir.x*(this.changeDirCount-SIZE)):0),
							 this.pos.y + this.currVertex[3] + ((prevDir.y*this.currVertex[3]>0)?(prevDir.y*(this.changeDirCount-SIZE)):0));

			endShape(CLOSE);

			this.changeDirCount+=STEP;
			if(this.changeDirCount >= SIZE ) {
				this.isChangingDir=false;
			}
		}
		else
		{
			drawingContext.shadowOffsetX = SHADOW[this.dirIndex].x*SHADOW_OFFSET;
			drawingContext.shadowOffsetY = SHADOW[this.dirIndex].y*SHADOW_OFFSET;
			fill(this.currColor);
				beginShape();
				vertex(this.pos.x + this.currVertex[0], this.pos.y + this.currVertex[1]);
				vertex(this.pos.x + this.currVertex[2], this.pos.y + this.currVertex[1]);
				vertex(this.pos.x + this.currVertex[2], this.pos.y + this.currVertex[3]);
				vertex(this.pos.x + this.currVertex[0], this.pos.y + this.currVertex[3]);
			endShape(CLOSE);
		}

		let step = this.currDir.copy();
		step.mult(STEP);
		this.pos.add(step);
		this.length += STEP;
	}

	checkNewDirection()
	{
		if((this.length > (SIZE+2)) && ((this.nextLength-this.length) <= 0 || !this.isValidDir(this.dirIndex)))
		{
			let nextIndex = this.mod(this.dirIndex + ((Math.random()>0.5)?-1:1), 4);
			if(!this.isValidDir(nextIndex)) nextIndex = this.mod(nextIndex + 2, 4); //If turn outside, go opposite direction

			this.prevIndex = this.dirIndex;
			this.dirIndex = nextIndex;
		//console.log("Change Direction: "+this.dirIndex);

			return true;
		}else{
			return false;
		}
	}

	isValidDir (dir)
	{
		let futureStep = DIRS[dir].copy();
		futureStep.mult(SIZE*2);
		let futurePos = futureStep.add(this.pos);
		return this.insideCanvas(futurePos.x, futurePos.y);
	}

	insideCanvas (x, y) 
	{
		return x >= 0 && x <= width &&
					 y >= 0 && y <= height;
	}

	mod(n, m) {
		return ((n % m) + m) % m;
	}

}

